create function public.hayna_can_insert_conversation_member(p_conversation uuid,p_member uuid) returns boolean language plpgsql security definer set search_path='' as $$ declare actor uuid:=auth.uid(); begin if actor is null or not exists(select 1 from public.profiles where id=actor and not is_banned) or not exists(select 1 from public.conversations where id=p_conversation and created_by=actor) then return false; end if; perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('conversation-members:'||p_conversation::text,0)); if p_member<>actor and not public.hayna_can_dm(actor,p_member) then return false; end if; return exists(select 1 from public.conversation_members where conversation_id=p_conversation and user_id=p_member) or (select count(*) from public.conversation_members where conversation_id=p_conversation)<2; end $$; revoke all on function public.hayna_can_insert_conversation_member(uuid,uuid) from public,anon; grant execute on function public.hayna_can_insert_conversation_member(uuid,uuid) to authenticated; alter policy conversation_members_creator_guard on public.conversation_members with check(public.hayna_can_insert_conversation_member(conversation_id,user_id));
